import{_ as d,o as e,c as a,a2 as l}from"./chunks/framework.CHeM0PsO.js";const i="/images/redemptioncontrol/36df6e9f-00e9-4db0-9767-7d866e9b760b.png",u=JSON.parse('{"title":"投后-回购事项管理小程序","description":"","frontmatter":{"title":"投后-回购事项管理小程序","date":"2026-08-26T00:00:00.000Z","category":"工作作品","summary":"当投后项目越来越多时，如何及时管理并实时更新投后回购事项。适用对象：投资机构投后团队、法务、基金运营人员。","tags":[]},"headers":[],"relativePath":"agents/redemptioncontrol.md","filePath":"agents/redemptioncontrol.md","lastUpdated":1788339898000}'),r={name:"agents/redemptioncontrol.md"};function o(n,t,h,s,c,p){return e(),a("div",null,[...t[0]||(t[0]=[l('<h1 id="投后-回购事项管理小程序" tabindex="-1">投后-回购事项管理小程序 <a class="header-anchor" href="#投后-回购事项管理小程序" aria-label="Permalink to &quot;投后-回购事项管理小程序&quot;">​</a></h1><p>一、这是什么工具</p><p>“回购项目小程序”是一套面向股权投资项目的回购事项管理台账。它把原本分散在投资协议、股东协议、测算底稿和日常沟通记录中的信息，统一整理为可查询、可筛选、可编辑、可导出的项目清单。</p><p>它主要解决四个问题：</p><ol><li><strong>什么时候可能触发回购</strong>：记录回购到期日，并自动计算剩余天数或逾期天数。</li><li><strong>什么情况下可以主张回购</strong>：结构化记录未上市、重大违约、控制权变更、创始人离职、诚信问题、其他股东行权等触发事项。</li><li><strong>回购后能收回多少钱</strong>：记录回购义务人、本金、利率、单利或复利、计息期间、股息红利及公允价值孰高等计算规则。</li><li><strong>项目是否具备实际偿付能力</strong>：结合企业现金、经营状况、融资进展、回购顺位和在先金额，对可执行性作出判断。</li></ol><p>当前版本可作为投后团队的“回购风险驾驶舱”：打开页面即可看到项目总数、近期到期项目、逾期项目、覆盖基金和已有跟进事项，并能快速定位需要优先处理的项目。</p><h2 id="二、当前版本已经实现的功能" tabindex="-1">二、当前版本已经实现的功能 <a class="header-anchor" href="#二、当前版本已经实现的功能" aria-label="Permalink to &quot;二、当前版本已经实现的功能&quot;">​</a></h2><ul><li>自动显示当天日期；</li><li>自动计算项目回购倒计时，并按紧急程度显示状态；</li><li>根据到期日自动判断“已触发／未触发”；</li><li>展示项目总数、90 天内到期、已逾期、覆盖基金、已有进展／Todo 等统计；</li><li>对项目、事项、措施和回购计算进行全文搜索；</li><li>按每个业务字段精确筛选；</li><li>新增项目；</li><li>点击任意项目单元格进入编辑；</li><li>将筛选后的结果导出为 CSV；</li><li>默认使用浏览器本地存储保存修改；</li><li>在通过 HTTP 运行时，尝试连接 <code>/repurchase-api</code>，支持后续扩展云端同步。</li></ul><h2 id="三、使用教程" tabindex="-1">三、使用教程 <a class="header-anchor" href="#三、使用教程" aria-label="Permalink to &quot;三、使用教程&quot;">​</a></h2><h3 id="_1-查看整体风险" tabindex="-1">1. 查看整体风险 <a class="header-anchor" href="#_1-查看整体风险" aria-label="Permalink to &quot;1. 查看整体风险&quot;">​</a></h3><p>打开页面后，先看顶部统计卡片：</p><ul><li><strong>项目总数</strong>：当前筛选范围内的项目数量；</li><li><strong>90 天内到期</strong>：到期日在今天至未来 90 天内的项目；</li><li><strong>已逾期</strong>：到期日早于今天的项目；</li><li><strong>覆盖基金</strong>：当前结果涉及的基金数量；</li><li><strong>已有进展／Todo</strong>：已经填写跟进记录的项目数量；</li><li><strong>风险事项含已触发</strong>：仅在存在相关项目时显示，表示“风险事项”文字中明确包含“已触发”的项目数量。</li></ul><p>统计卡片会随搜索和筛选结果同步变化，因此既能看全局，也能看某一基金或某类风险的局部统计。</p><h3 id="_2-快速查找项目" tabindex="-1">2. 快速查找项目 <a class="header-anchor" href="#_2-快速查找项目" aria-label="Permalink to &quot;2. 快速查找项目&quot;">​</a></h3><p>在搜索框输入项目名称、回购义务人、风险关键词或处置措施。例如输入“知识产权”“创始人离职”或“10% 单利”，系统会在全部可维护字段中查找匹配内容。</p><p>如需精确定位，可使用“字段筛选”：</p><ul><li>按基金查看；</li><li>按回购到期日查看；</li><li>按“是否触发回购”查看；</li><li>按回购顺位、回购计算、回购能力评价等字段查看。</li></ul><p>搜索和多个字段筛选可以叠加。点击“清空筛选”即可恢复完整台账。</p><h3 id="_3-理解倒计时" tabindex="-1">3. 理解倒计时 <a class="header-anchor" href="#_3-理解倒计时" aria-label="Permalink to &quot;3. 理解倒计时&quot;">​</a></h3><p>倒计时由“回购到期日”自动生成：</p><ul><li>到期日早于今天：显示“逾期 N 天”；</li><li>到期日等于今天：显示“今天到期”；</li><li>距到期日不超过 90 天：显示“剩余 N 天”，并作为近期项目提示；</li><li>距到期日超过 90 天：显示普通剩余天数；</li><li>未填写或日期无效：显示“无到期日”。</li></ul><p>当前“是否触发回购”的自动规则只依据到期日：到期日小于或等于今天为“已触发”，否则为“未触发”。但法律文件中的重大违约、控制权变更等事件可能在到期日前提前触发，因此最终判断仍应由投后或法务人员复核。</p><h3 id="_4-新增项目" tabindex="-1">4. 新增项目 <a class="header-anchor" href="#_4-新增项目" aria-label="Permalink to &quot;4. 新增项目&quot;">​</a></h3><p>点击“新增项目”，依次填写基金、项目名称、到期日、回购事项、风险事项、处置措施等内容。项目名称为必填项，其他信息可以分阶段补充。</p><p>推荐录入顺序：</p><ol><li>先填写基金、项目名称、回购到期日；</li><li>从最终签署的交易文件中摘录回购触发事项；</li><li>核对回购义务人、价格公式和回购顺位；</li><li>根据最新经营及现金情况填写风险事项和回购能力；</li><li>将下一步行动写入“进展及 Todo”，同时注明责任人和日期。</li></ol><h3 id="_5-编辑项目" tabindex="-1">5. 编辑项目 <a class="header-anchor" href="#_5-编辑项目" aria-label="Permalink to &quot;5. 编辑项目&quot;">​</a></h3><p>点击项目台账中的任意可编辑单元格，会打开该项目的完整编辑窗口，并自动聚焦到所点击字段。修改后点击“保存修改”。</p><p>通过 <code>file://</code> 直接打开时，修改保存在当前浏览器本地；更换电脑、浏览器、浏览器配置或清理站点数据后，内容可能无法保留。正式多人使用前应接入后端数据库和权限系统。</p><h3 id="_6-导出结果" tabindex="-1">6. 导出结果 <a class="header-anchor" href="#_6-导出结果" aria-label="Permalink to &quot;6. 导出结果&quot;">​</a></h3><p>先完成搜索和筛选，再点击“导出筛选结果”。系统会导出当前结果，而不是全部数据。CSV 文件包含中文表头和自动生成的倒计时，可用 Excel 或其他表格工具打开。</p><h2 id="四、具体设置了哪些维度" tabindex="-1">四、具体设置了哪些维度 <a class="header-anchor" href="#四、具体设置了哪些维度" aria-label="Permalink to &quot;四、具体设置了哪些维度&quot;">​</a></h2><h3 id="a-11-个可维护业务维度" tabindex="-1">A. 11 个可维护业务维度 <a class="header-anchor" href="#a-11-个可维护业务维度" aria-label="Permalink to &quot;A. 11 个可维护业务维度&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:right;">序号</th><th>维度</th><th>字段标识</th><th>作用</th><th>建议填写口径</th></tr></thead><tbody><tr><td style="text-align:right;">1</td><td>基金</td><td><code>fund</code></td><td>标识项目所属基金</td><td>使用统一的基金简称，不混用全称和简称</td></tr><tr><td style="text-align:right;">2</td><td>项目名称</td><td><code>projectName</code></td><td>项目主索引，也是唯一必填业务字段</td><td>使用投后台账中的标准项目名称</td></tr><tr><td style="text-align:right;">3</td><td>回购到期日</td><td><code>dueDate</code></td><td>生成倒计时和期限触发状态</td><td>填写最早需重点监控的明确日期，格式为 <code>YYYY-MM-DD</code></td></tr><tr><td style="text-align:right;">4</td><td>进展及 Todo</td><td><code>progressTodo</code></td><td>记录当前进展和下一步行动</td><td>建议采用“日期—责任人—事项—截止日”格式</td></tr><tr><td style="text-align:right;">5</td><td>回购事项</td><td><code>repurchaseEvents</code></td><td>记录合同约定的全部触发条件</td><td>以最终签署文件为准，保留条件、期限、例外和补救期</td></tr><tr><td style="text-align:right;">6</td><td>风险事项</td><td><code>riskEvents</code></td><td>记录已发生或可能发生的事实风险</td><td>区分“已发生、待核实、可能触发”，注明证据来源</td></tr><tr><td style="text-align:right;">7</td><td>拟采取措施</td><td><code>measures</code></td><td>记录投后处置方案</td><td>写明沟通、函件、测算、谈判、诉讼准备等动作</td></tr><tr><td style="text-align:right;">8</td><td>回购顺位</td><td><code>priority</code></td><td>判断不同轮次、不同投资人的偿付先后</td><td>按协议明确优先级；无约定时标注“待核实”</td></tr><tr><td style="text-align:right;">9</td><td>在先回购金额</td><td><code>priorAmount</code></td><td>评估排在本基金前面的偿付压力</td><td>填写金额、币种、对应轮次和测算日期</td></tr><tr><td style="text-align:right;">10</td><td>回购计算</td><td><code>calculation</code></td><td>记录回购义务人与价格公式</td><td>明确本金、利率、单复利、计息起止日、股息及孰高规则</td></tr><tr><td style="text-align:right;">11</td><td>回购能力评价</td><td><code>capacity</code></td><td>评价义务人的实际支付能力</td><td>结合现金、融资、盈利、资产、债务和其他回购请求作判断</td></tr></tbody></table><h3 id="b-2-个自动派生维度" tabindex="-1">B. 2 个自动派生维度 <a class="header-anchor" href="#b-2-个自动派生维度" aria-label="Permalink to &quot;B. 2 个自动派生维度&quot;">​</a></h3><table tabindex="0"><thead><tr><th>维度</th><th>生成方式</th><th>当前规则</th></tr></thead><tbody><tr><td>倒计时</td><td>根据回购到期日与当天日期计算</td><td>逾期、今天到期、90 天内、90 天以上、无到期日</td></tr><tr><td>是否触发回购</td><td>根据倒计时生成</td><td>到期日小于或等于今天为“已触发”，其余为“未触发”</td></tr></tbody></table><h3 id="c-5-1-个统计维度" tabindex="-1">C. 5+1 个统计维度 <a class="header-anchor" href="#c-5-1-个统计维度" aria-label="Permalink to &quot;C. 5+1 个统计维度&quot;">​</a></h3><p>常驻统计为项目总数、90 天内到期、已逾期、覆盖基金、已有进展／Todo；当风险事项中存在“已触发”字样时，额外显示“风险事项含已触发”。</p><h2 id="附件图片" tabindex="-1">附件图片 <a class="header-anchor" href="#附件图片" aria-label="Permalink to &quot;附件图片&quot;">​</a></h2><p><img src="'+i+'" alt="投后-回购事项管理小程序 - 36df6e9f-00e9-4db0-9767-7d866e9b760b.png"></p>',40)])])}const b=d(r,[["render",o]]);export{u as __pageData,b as default};
